  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.travelpayouts.com/blog/best-travel-insurance-affiliate-programs/', 'affiliate_network', 'affiliate', 'Travelpayouts'' travel insurance roundup lists EKTA at 20% of the order amount with a 30-day cookie lifetime, deep link generator, pre-made links and banners, joining via Travelpayouts; it notes commission is paid as soon as the insurance policy begins. One minor directory (GistJunction) lists 25%, an outlier against the network''s own repeated 20% figure, documented here.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://outofyourcomfortzone.net/ekta-international-travel-insurance-complete-review-with-pros-and-cons/', 'listing', 'general', 'An in-depth review describes EKTA as a Ukrainian travel insurance company founded in 2018 with more than 2 million customers around the world, selling medical and travel coverage online.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 16, 5, 9, 4, '{"compensation": "20% of the order amount per Travelpayouts'' own program pages \u2014 among the highest travel-insurance rates \u2014 with payout when the policy begins rather than after the trip; no cap statement found.", "contact_access": "No public affiliate email found; contact runs through the Travelpayouts dashboard.", "credibility": "A Ukrainian insurer founded in 2018 reporting 2M+ customers, distributed through the established Travelpayouts network.", "niche_fit": "Travel insurance is a standard, repeatable recommendation for travel creators, and EKTA''s low starting price suits budget-travel audiences.", "opportunity_availability": "Open to join through Travelpayouts with easy approval reported by directories.", "ugc_evidence": "Program materials explicitly allow social networks, messengers and content projects as traffic sources, though there is no dedicated creator program layer."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Campspot', 'https://www.campspot.com', 'Instant-booking platform for campgrounds, RV parks, cabins and glamping across North America, with real-time availability and a lowest-price guarantee; its affiliate program on Awin pays 3% on every booking with a 30-day cookie.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 3, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/22326.', 'https://ui.awin.com/merchant-profile/22326', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Campspot Affiliate Program (Awin)', 'https://ui.awin.com/merchant-profile/22326', 'https://ui.awin.com/merchant-profile/22326', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/22326', 'affiliate_network', 'affiliate', 'Campspot''s official Awin merchant profile (US program, merchant 22326) states: ''3% commission on every booking'', a 30-day cookie period, a full design and content library and fast, easy integration; it describes Campspot as an instant-booking platform for camping across North America covering campgrounds, RV parks, cabins and glamping. (A 2021 launch report had described the program''s network differently; the live Awin profile fetched for this entry settles the network as Awin.)', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 8, 5, 9, 5, '{"compensation": "3% on every booking per the official Awin profile \u2014 a low rate, though booking values for multi-night stays are sizeable; no cap statement found.", "contact_access": "No public affiliate email found; access runs through Awin only.", "credibility": "A leading North American camping-booking platform with premium inventory and a lowest-price guarantee, listed on a major network.", "niche_fit": "Camping, RV and glamping content is a large, growing travel-creator niche, and Campspot covers the full range of outdoor stays.", "opportunity_availability": "Open application through Awin with a full design and content library provided.", "ugc_evidence": "A formal network affiliate program with content assets for publishers; no dedicated creator or ambassador layer was found."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Plum Guide', 'https://www.plumguide.com', 'Curated vacation-rental platform that vets every home with a 150-point quality test, accepting only the top few percent of homes reviewed, across the UK, US, EU and Australia; its affiliate programme runs on Partnerize and pays 1% to 10% per sale, with top partners reaching the 10% VIP rate.', 'United Kingdom', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'plumguide@silverbean.com', null, 'https://downloads.ctfassets.net/i3kf1olze1gn/6fHfHaHf177566K2VxGAVd/a6309f26d06de242bf6db9126432f89e/Plum_Guide_-_Affiliate_guide_21.pdf', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Partnerize', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://downloads.ctfassets.net/i3kf1olze1gn/6fHfHaHf177566K2VxGAVd/a6309f26d06de242bf6db9126432f89e/Plum_Guide_-_Affiliate_guide_21.pdf.', null, 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Plum Guide Affiliate Programme (Partnerize)', null, 'https://downloads.ctfassets.net/i3kf1olze1gn/6fHfHaHf177566K2VxGAVd/a6309f26d06de242bf6db9126432f89e/Plum_Guide_-_Affiliate_guide_21.pdf', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://downloads.ctfassets.net/i3kf1olze1gn/6fHfHaHf177566K2VxGAVd/a6309f26d06de242bf6db9126432f89e/Plum_Guide_-_Affiliate_guide_21.pdf', 'official_site', 'affiliate', 'Plum Guide''s own affiliate guide states the programme runs on the Partnerize network (with UK, US, EU and AU programmes), is free to join, and that affiliates ''earn from 1% to 10% commission per sale''; it publishes the affiliate team contact plumguide@silverbean.com and offers bespoke codes, CPA increases and paid tenancy for partners. The top of the brand''s own published range (10%) is recorded as the rate, with the full range documented here.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/plumguide-us/', 'listing', 'affiliate', 'Lasso''s directory lists the Plumguide US affiliate program at 10% per sale with a 90-day cookie, consistent with the top of the range in the brand''s own guide; roundups describe standard rates starting around 7% with VIP partners at 10%.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 13, 13, 8, 5, '{"compensation": "1% to 10% per sale in the brand''s own affiliate guide, with standard partners around 7% and VIP partners at 10% per roundups \u2014 the top of the brand''s own published range is recorded; no cap statement found.", "contact_access": "A dedicated affiliate team email (plumguide@silverbean.com) is published in the brand''s own affiliate guide.", "credibility": "An established, venture-backed London platform known for rigorously vetting every listed home.", "niche_fit": "Design-led, high-quality vacation homes are premium travel content for destination and luxury-travel creators.", "opportunity_availability": "Free to join via Partnerize across four market programmes, subject to approval.", "ugc_evidence": "The programme offers bespoke codes, creative assets and CPA increases for exposure per the brand''s own guide, though it is publisher-led rather than a social creator program."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Compensair', 'https://www.compensair.com', 'Flight-compensation claims service (Compensair Pte. Ltd., registered in Singapore, founded 2016) that helps passengers claim up to €600 for delayed, cancelled or overbooked flights on a no-win, no-fee basis; its affiliate program on Travelpayouts pays a flat bounty per confirmed application.', 'Singapore', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Travelpayouts', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.travelpayouts.com/blog/compensair-increased-commision-and-a-new-widget/amp/.', 'https://www.travelpayouts.com/blog/compensair-increased-commision-and-a-new-widget/amp/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Compensair Affiliate Program (Travelpayouts)', 'https://www.travelpayouts.com/blog/compensair-increased-commision-and-a-new-widget/amp/', 'https://www.travelpayouts.com/blog/compensair-increased-commision-and-a-new-widget/amp/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.travelpayouts.com/blog/compensair-increased-commision-and-a-new-widget/amp/', 'affiliate_network', 'affiliate', 'Travelpayouts'' own Compensair program post states the affiliate commission is a flat bounty: a basic 10 euro per confirmed application from all countries except Spain, Turkey, Italy, Romania, Ireland and Greece (5 euro), rising per confirmed claim at 10+ applications depending on the applicant''s country (up to 25 euro). Because the program pays flat per-application bounties rather than a percentage — and an older Travelpayouts post quoted 5 euro per claim sent to airlines — commission_rate is null and the flat structure is documented here.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.compensair.com/en/terms-and-conditions/', 'official_site', 'general', 'Compensair''s own terms name the operator as Compensair Pte.Ltd., a company registered in Singapore, and describe the service: claiming monetary compensation from airlines for flight delay, cancellation and denied boarding, charging clients only on success.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 10, 10, 5, 9, 4, '{"compensation": "Flat bounties per confirmed application (\u20ac10 base, \u20ac5 for six listed countries, up to \u20ac25 at volume) per Travelpayouts'' own program post \u2014 predictable per-claim pay, but no percentage rate applies, so none is recorded.", "contact_access": "No public affiliate email found; contact runs through Travelpayouts.", "credibility": "Operating since 2016 as a Singapore-registered claims company claiming against 150+ airlines in 60 countries per its own site and reviews.", "niche_fit": "Flight-delay compensation is a highly shareable travel-tips topic, and the free eligibility check gives creators an easy call to action.", "opportunity_availability": "Open to join through Travelpayouts with links, banners and a widget provided.", "ugc_evidence": "Program materials target travel content sites and bloggers; there is no dedicated creator or ambassador layer."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('MacroFactor', 'https://macrofactor.com', 'Nutrition and training app company run by Stronger By Science Technologies LLC (headquartered in Raleigh, North Carolina). Its two apps, MacroFactor Nutrition (adaptive macro/calorie tracking and nutrition coaching) and MacroFactor Workouts (personalized training programming), together serve more than 600,000 users, per the brand''s own partnership page.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'wellness'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://macrofactor.com/macrofactor-partnership/', 'https://macrofactor.com/macrofactor-partnership/', 'verified', now());
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'general', 'support@macrofactor.com', null, 'https://macrofactor.com/macrofactor-partnership/', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 40, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://macrofactor.com/macrofactor-partnership/.', 'https://macrofactor.com/macrofactor-partnership/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'MacroFactor Partnership Program (affiliate partnerships and paid sponsorships)', 'https://macrofactor.com/macrofactor-partnership/', 'https://macrofactor.com/macrofactor-partnership/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://macrofactor.com/macrofactor-partnership/', 'official_site', 'affiliate', 'MacroFactor''s official partnership page offers affiliate partnerships: partners receive a unique code giving their audience an extended free trial and earn commission when referred users become paying subscribers. The standard affiliate commission is stated verbatim as 40% of the user''s first subscription payment, with worked examples ($4.80 monthly, $19.20 six-month, $28.80 yearly, $36 yearly bundle). No earnings-cap statement appears on the page, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://macrofactor.com/macrofactor-partnership/', 'official_site', 'ugc_collab', 'The page says MacroFactor works with a select group of creators, educators, athletes and media partners in fitness, nutrition, training and health; it lists content formats it wants (YouTube integrations and Shorts, Instagram Reels/posts/Stories, TikTok posts, podcast and newsletter sponsorships), names eight creators it has partnered with (including Jesse James West, Will Tennyson and Lean Beef Patty), offers paid sponsorships alongside the affiliate option, and links an open partnership application form. ''Select group'' is a relative claim with no creator count, so saturation is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://madeometer.com/p/69787477829aeccd39b40f67/MacroFactor-nutrition-app', 'listing', 'general', 'Madeometer''s company profile states MacroFactor is headquartered in Raleigh, North Carolina, and is managed by Stronger By Science Technologies LLC; the app launched in September 2021.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 17, 18, 12, 9, 5, '{"compensation": "A published, high rate on the brand''s own page: 40% of the referred user''s first subscription payment, with dollar examples for each plan tier.", "contact_access": "A public partnership application form on the official page plus a published support email \u2014 near the top band, though no dedicated partnerships inbox is published.", "credibility": "Established app business (Stronger By Science Technologies LLC, Raleigh NC) reporting more than 600,000 users across its two apps on its own page.", "niche_fit": "Nutrition coaching and workout apps built for fitness/nutrition creators \u2014 squarely in the wellness UGC niche, with the brand explicitly recruiting fitness, nutrition, training and health creators.", "opportunity_availability": "The application form is publicly open on the partnership page to creators, educators, athletes and media partners.", "ugc_evidence": "The official page names eight creators it has partnered with, lists the exact content formats it buys (YouTube integrations/Shorts, Reels, TikTok, podcasts, newsletters) and offers both affiliate and paid-sponsorship tracks."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Persona Nutrition', 'https://www.personanutrition.com', 'Personalized vitamin pack subscription service (Vitamin Packs Inc. dba Persona Nutrition, based at 35131 SE Douglas St, Unit 110, Snoqualmie, WA 98065). Customers take an online assessment and receive dietitian-guided daily vitamin packs tailored to their diet, lifestyle and medication interactions, delivered by subscription.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'health'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://www.personanutrition.com/affiliate-partners/', 'https://www.personanutrition.com/affiliate-partners/', 'verified', now());
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'general', 'info@personanutrition.com', null, 'https://www.personanutrition.com/affiliate-partners/', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.personanutrition.com/affiliate-partners/.', 'https://www.personanutrition.com/affiliate-partners/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Persona Affiliate Partner Program ("Join the Pack" influencer community)', 'https://www.personanutrition.com/affiliate-partners/', 'https://www.personanutrition.com/affiliate-partners/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.personanutrition.com/affiliate-partners/', 'official_site', 'affiliate', 'Persona''s official Affiliate Partner page (''JOIN THE PACK'') invites influencers to join its influencer community and introduce personalized vitamin packs to their audience, with a ''Get Started with Persona'' application route. The page publishes no commission rate, so no rate could be verified from the brand itself.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://theaffiliateslist.com/supplement-affiliate-programs/', 'listing', 'compensation', 'Third-party sources conflict on Persona''s affiliate pay, so commission_rate is null: TheAffiliatesList reports a $25 flat bounty per qualified subscription on a Direct/Impact program with a 30-day cookie, while InfluencerMarketingHub (influencermarketinghub.com/supplement-affiliate-programs/) and BrandAndPartners (brandandpartners.com/supplement-affiliate-programs/) both report 25% per sale. The network is recorded as Impact per TheAffiliatesList.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.personanutrition.com/affiliate-partners/', 'official_site', 'general', 'The official page publishes Persona''s contact details: info@personanutrition.com, phone 1-800-983-3887, and the address 35131 SE Douglas St, Unit 110, Snoqualmie WA 98065. Note: Persona''s separate customer Refer-a-Friend scheme pays $20 in store credit (capped at $200/month) per its refer-a-friend terms — that store-credit scheme is NOT the basis of this entry; the entry rests on the influencer/affiliate program above.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 8, 13, 8, 5, '{"compensation": "Third-party listings agree a paid affiliate program exists but conflict on the pay itself ($25 flat per subscription vs 25% per sale), and the brand publishes no rate \u2014 so the rate is recorded as null and compensation scores mid-low.", "contact_access": "A public affiliate application page on the official site plus a published general email and phone number \u2014 top band per the rubric.", "credibility": "Established subscription brand (Vitamin Packs Inc., Snoqualmie WA) covered by Forbes, ABC News, The Oprah Magazine and Health/Shape per BrandAndPartners'' profile.", "niche_fit": "Personalized daily vitamin packs are a core wellness-creator product, and the program page is written directly for wellness influencers.", "opportunity_availability": "The ''Get Started with Persona'' route on the official affiliate page is publicly open to influencers.", "ugc_evidence": "An official influencer community (''Join the Pack'') with an application route exists on the brand''s own site, though no named creator partners or content deliverables are published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('SelfDecode', 'https://selfdecode.com', 'Consumer genomics and personalized health platform founded in 2016 and based in Miami, Florida (CB Insights). SelfDecode turns DNA data and lab results into personalized health reports and recommendations using polygenic risk scores and AI, sold as DNA kits, health analysis plans and add-on reports by subscription.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'health'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://selfdecode.com/en/affiliate-program/', 'https://selfdecode.com/en/affiliate-program/', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Reported rate range: 10-25% (recorded as a range; no single numeric rate). Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://selfdecode.com/en/affiliate-program/.', 'https://selfdecode.com/en/affiliate-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'SelfDecode Health Affiliate Program', 'https://selfdecode.com/en/affiliate-program/', 'https://selfdecode.com/en/affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://selfdecode.com/en/affiliate-program/', 'official_site', 'affiliate', 'SelfDecode''s official affiliate program page (''Health Affiliate Program - Earn 25% Commission'') describes a tiered affiliate system with a 90-day cookie, monthly payouts via PayPal or bank transfer, a marketing kit and a dedicated affiliate support team. It explicitly recruits biohackers, content creators focused on health/wellness/genetics, health coaches and fitness, nutrition and mental-health influencers. No earnings-cap statement appears, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://selfdecode.com/en/referral/', 'official_site', 'compensation', 'SelfDecode''s official referral page states that affiliate commissions start at 10%, with potential for increased earnings based on performance — consistent with the affiliate page''s ''up to 25%'' headline and tier system, so the rate is recorded as a 10-25% range. (The same page''s separate friends-and-family scheme pays a $50 Amazon gift card per referred subscription; that is not the affiliate commission.)', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/selfdecode/', 'affiliate_network', 'affiliate', 'Lasso''s affiliate directory lists the SelfDecode affiliate program at up to 25% commission with a 90-day cookie, a $50 payout threshold, and joining via the Impact affiliate platform with manual approval for applicants with a relevant health/nutrition/genetics audience.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.cbinsights.com/company/selfdecode', 'listing', 'general', 'CB Insights profiles SelfDecode as founded in 2016 and headquartered in Miami, Florida, providing health insights through DNA analysis, including genetic risk assessments and an AI health coach.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 16, 11, 8, 4, '{"compensation": "Published tiered pay on the brand''s own pages: commissions start at 10% and rise to 25% with performance, on a 90-day cookie.", "contact_access": "A public program page with a detailed FAQ and a stated affiliate support team, but no published partnerships email \u2014 upper-mid band.", "credibility": "Operating since 2016 with a 4.7/5 rating across 750 reviews cited on its own program pages; a mid-size specialist rather than a mass-market brand.", "niche_fit": "DNA-based personalized health reports are a strong fit for health, biohacking and wellness creators, whom the program page names directly.", "opportunity_availability": "The affiliate program is publicly documented on the brand''s own site with joining routed through Impact and manual approval.", "ugc_evidence": "The brand''s own program page is written for content creators and influencers and provides a marketing kit and affiliate support, though no named creator partners are published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('North Spore', 'https://www.northspore.com', 'Maine-based mushroom cultivation company launched in 2014 by a mycologist, an organic farmer and a photojournalist. North Spore sells ready-to-fruit mushroom grow kits, grain/sawdust/plug spawn, substrates and cultivation tools and equipment for growing gourmet and medicinal mushrooms at home or commercially, alongside educational mycology content.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'food-drink'), true);
