  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/north-spore/', 'affiliate_network', 'affiliate', 'LinkClicky''s affiliate directory lists North Spore''s affiliate program on the Impact platform at 10% commission per sale, described as the rate officially listed with the program (page last updated March 11, 2024), with joining routed through Impact. No cap or creator-count data is published, so cap and saturation are recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://merchants.sovrn.com/merchants/218072/north-spore-affiliate-program', 'listing', 'general', 'Sovrn Commerce''s merchant profile describes North Spore as a Maine-based mushroom cultivation company founded in 2014 by three friends with backgrounds in mycology, biology and the arts, selling grow kits, spawn, substrates and indoor/outdoor cultivation equipment.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://northspore.com/pages/exclusive-discount-for-members', 'official_site', 'contact', 'North Spore''s official site publishes a partnership route for organizations (an exclusive 10% member discount code program for mushroom, foraging, outdoor and education organizations) with applications directed to jill@northspore.com — evidence the brand runs partner programs and publishes a contact for them.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 10, 12, 7, 6, 4, '{"compensation": "A published network rate exists \u2014 10% per sale on Impact per the network directory \u2014 a mid-range rate for the category.", "contact_access": "A published partnerships contact email on the official site (for organization programs), but the affiliate route itself is only via the Impact marketplace \u2014 mid band.", "credibility": "Specialist category leader operating since 2014 with a full cultivation-supply catalog and educational resources.", "niche_fit": "Mushroom grow kits and cultivation supplies sit in the food/gardening creator niche \u2014 grow-along and harvest content is highly visual, though narrower than mainstream food brands.", "opportunity_availability": "Creators join by applying to the program inside Impact; there is no brand-hosted application page.", "ugc_evidence": "The brand is built around educational mycology content and runs partner programs, but no creator-specific program page or named creator partners were found."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Vivo Life', 'https://www.vivolife.co.uk', 'UK plant-based nutrition brand selling nutrient-dense vegan supplements and fitness nutrition, including the Perform plant-based protein line, through its own UK/US web stores. Its affiliate programme recruits promoters across social media, blogs and podcasts to spread the word about plant-based health products.', 'United Kingdom', 'published') returning id into bid;
