  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Social Snowball', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.vivolife.co.uk/pages/social-snowball-affiliate-terms-and-conditions.', 'https://www.vivolife.co.uk/pages/social-snowball-affiliate-terms-and-conditions', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Vivo Life Affiliate Programme (Social Snowball)', 'https://www.vivolife.co.uk/pages/social-snowball-affiliate-terms-and-conditions', 'https://www.vivolife.co.uk/pages/social-snowball-affiliate-terms-and-conditions', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.vivolife.co.uk/pages/social-snowball-affiliate-terms-and-conditions', 'official_site', 'affiliate', 'Vivo Life''s official Social Snowball affiliate terms page publishes the program terms: base commission 10.00%, commission type percent of sale, 30-day cookie, conversion on online purchase with processed valid payment. It invites applicants to complete the form on the page to earn commission from a personal link, describing a worldwide network of promoters using social media, online content, blogs and podcasts. No earnings-cap statement appears, so the cap is recorded as unknown; ''worldwide network'' is a relative claim, so saturation is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkmydeals.com/affiliate-programs/info/vivolife.co.uk/', 'affiliate_network', 'affiliate', 'LinkMyDeals'' network roundup shows Vivo Life also runs campaigns on Awin (including a Vivo Life UK merchant listing), corroborating an active multi-channel affiliate operation alongside the brand''s own Social Snowball programme, whose published 10% base rate governs this entry.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 13, 11, 8, 4, '{"compensation": "Published pay in the brand''s own terms: 10% base commission on the percent-of-sale program with a 30-day cookie.", "contact_access": "An application form on the official programme page itself; no separate partnerships email is published \u2014 upper-mid band.", "credibility": "Established UK plant-based nutrition brand with international web stores and an additional Awin network presence.", "niche_fit": "Plant-based protein and supplements for fitness and wellness audiences \u2014 a proven creator niche, with the programme explicitly aimed at social, blog and podcast promoters.", "opportunity_availability": "Applications are open via the form on the brand''s own programme page (approval at the brand''s discretion).", "ugc_evidence": "A formal affiliate programme with published terms on the brand''s own site and promotion rules written for social media creators, though no named creator partners are published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Fairhaven Health', 'https://www.fairhavenhealth.com', 'Women''s health company based in Bellingham, Washington, making science-based fertility, pregnancy, nursing and broader women''s health products since 2003 — including the FertilAid and FH PRO supplement lines, the OvaCue fertility monitor and BabyDance fertility lubricant — sold through its own site and healthcare providers.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'health'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'ShareASale', 15, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://getlasso.co/affiliate/fairhaven-health/.', null, 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/fairhaven-health/', 'affiliate_network', 'affiliate', 'Lasso''s affiliate directory lists the Fairhaven Health affiliate program at 15% commission per sale with a 30-day cookie and a $50 payout threshold, with joining routed through ShareASale. No cap or creator-count data is published, so cap and saturation are recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affilorama.com/blog/natural-fertility-affiliate-programs-are-they-still-productive', 'listing', 'affiliate', 'Affilorama''s 2026 fertility-program comparison independently lists Fairhaven Health at 15% commission on the full cart, 30-day cookie, via ShareASale. An older directory (affiliateprograms.com) describes a 10-20% range with the OvaCue fertility monitor at 10%; the standard 15% rate is corroborated by both current sources and is the rate recorded.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.cbinsights.com/company/fairhaven-health', 'listing', 'general', 'CB Insights profiles Fairhaven Health as based in Bellingham, Washington, offering supplements and tools for fertility enhancement, prenatal care, postnatal nursing and vaginal health; the brand dates to 2003 and is now part of Blueroot Health per its 2025 GlobeNewswire release.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 10, 14, 5, 6, 5, '{"compensation": "Published pay: 15% per sale on the full cart (30-day cookie) per two independent current directories \u2014 a solid rate for the niche.", "contact_access": "No public partnerships email or brand-hosted application page was found; joining is handled inside ShareASale \u2014 lower band.", "credibility": "Operating since 2003, ISO-13485 certified, with products recommended by healthcare practitioners and sold through clinics.", "niche_fit": "Fertility, pregnancy and nursing products map directly onto the large TTC and women''s-health creator community.", "opportunity_availability": "Creators apply through the ShareASale marketplace listing rather than an open brand page.", "ugc_evidence": "A long-running affiliate program marketed to women''s-health bloggers and influencers, but no brand-run creator community or named creator partners were found."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Headspace', 'https://www.headspace.com', 'Leading mental health app offering guided meditation, sleep content and tools for stress, anxiety and processing thoughts, sold by subscription to consumers and through more than 4,000 employer organizations worldwide.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'wellness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.whichprogram.com/en/p/headspace-affiliate-program.', null, 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.whichprogram.com/en/p/headspace-affiliate-program', 'affiliate_network', 'affiliate', 'WhichProgram''s directory entry (collected September 11, 2026) records Headspace''s program on impact.com and quotes the network''s own statement: 3-8% commission on order value for subscriptions — 8% for annual subscriptions, 5% for monthly subscriptions, 3% for gift subscriptions — with a 45-day click attribution window, recurring commissions, US conversions only, and application required.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://geekchamp.com/13-best-meditation-affiliate-programs-in-2025-top-offers/', 'listing', 'compensation', 'Other sources conflict with the network statement, so commission_rate is null: GeekChamp reports approximately 15% per subscription via Impact, Uppromote (uppromote.com/affiliate-directory/headspace/) reports 20% of first-year subscription revenue, and UmaTechnology reports up to $15 per new subscriber. The tiered 3-8% network statement is the most detailed source, but the conflict prevents recording a single rate.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uppromote.com/affiliate-directory/headspace/', 'listing', 'ugc_collab', 'Uppromote''s directory entry records the program''s accepted traffic sources as including content/blogs, review sites, search and sub-affiliate/influencer networks, and notes Headspace partners with over 4,000 organizations worldwide — evidence the program is open to influencer-type promoters, not only coupon sites.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 11, 7, 5, 6, 5, '{"compensation": "Real published network terms exist (a tiered 3-8% of subscription order value, recurring), but third-party sources conflict (15%, 20%, $15 CPA), so the rate is recorded as null and compensation scores conservatively.", "contact_access": "No public partnerships email or brand-hosted application was found; everything runs through Impact \u2014 lower band.", "credibility": "One of the world''s largest mental-health apps, partnering with 4,000+ organizations, with a long-established subscription business.", "niche_fit": "Meditation, sleep and mental-health content is a core wellness-creator niche and Headspace is its best-known consumer brand.", "opportunity_availability": "Application is required through the Impact marketplace; acceptance is at the brand''s discretion.", "ugc_evidence": "The Impact program accepts influencer/sub-affiliate traffic per directory listings, but Headspace publishes no creator program page or named creator partners."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Thinx', 'https://www.thinx.com', 'New York-based femtech company that created the reusable period and incontinence underwear category, selling Thinx period underwear, Thinx (BTWN) for teens, Speax by Thinx and Thinx for All through its own site and mass retailers. Kimberly-Clark acquired a majority stake in February 2022.', 'United States', 'published') returning id into bid;
