  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Thinx Affiliate Program (via Partnerize / Ascend)', 'https://www.ascendpartner.com/affiliate/registration?refid=152557', 'https://www.ascendpartner.com/affiliate/registration?refid=152557', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.ascendpartner.com/affiliate/registration?refid=152557', 'affiliate_network', 'affiliate', 'Thinx''s affiliate program application is live on the Ascend (Partnerize) partner platform: the registration page asks applicants whether they are an individual who will promote brands on their personal social media or personal blog, confirming the program is open to individual creators, not only coupon/paid-search businesses.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/thinx/', 'affiliate_network', 'affiliate', 'Lasso''s affiliate directory confirms a Thinx affiliate program in the women''s health category but lists both the commission rate and cookie duration as unknown — Thinx does not publish its affiliate pay, so commission_rate is null. No cap or creator-count data is published, so cap and saturation are unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://en.wikipedia.org/wiki/Thinx', 'listing', 'general', 'Wikipedia profiles Thinx as a New York City-headquartered company selling period underwear, with Kimberly-Clark holding a majority stake since 2022. Note: Thinx also runs a separate customer referral scheme ($10 account credit per referral per RetailMeNot) — that store-credit scheme is not the basis of this entry; the entry rests on the Partnerize affiliate program above.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 5, 8, 7, 5, '{"compensation": "No published pay data: directories list the rate as unknown and the brand publishes no terms \u2014 at the no-data cap per the rubric.", "contact_access": "A live public application form on the Partnerize/Ascend platform, though no published partnerships email \u2014 mid band.", "credibility": "Category creator with national mass-retail distribution (Target, Walmart) and majority ownership by Kimberly-Clark since 2022.", "niche_fit": "Period care is a large, content-rich women''s-health niche and Thinx is its category-defining brand.", "opportunity_availability": "The application is publicly accessible and explicitly open to individual social-media promoters.", "ugc_evidence": "The program''s own application explicitly recruits individuals promoting on personal social media and blogs, but no creator community, named partners or published content terms were found."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Explorer Cold Brew', 'https://www.explorercoldbrew.com', 'US cold brew coffee company selling premium cold brew concentrates with customizable caffeine levels (from decaf to extra-caffeinated), plus brewing kits and accessories. The brand emphasizes sustainability through eco-friendly packaging and a partnership with One Tree Planted.', 'United States', 'published') returning id into bid;
