  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/explorer-cold-brew/', 'affiliate_network', 'affiliate', 'LinkClicky''s affiliate directory lists Explorer Cold Brew''s affiliate program on the ShareASale platform at 10% commission per sale with a 30-day cookie, described as the rate officially listed with the program (page last updated March 10, 2024). No cap or creator-count data is published, so cap and saturation are recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/explorer-cold-brew/', 'affiliate_network', 'affiliate', 'Lasso''s affiliate directory independently lists the Explorer Cold Brew affiliate program at 10% per sale with a 30-day cookie in the coffee/drink category, corroborating the ShareASale listing. (Shopper.com''s separate platform listing shows a 5-10% payout range for its own channel; the network-listed rate is 10%.)', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 9, 12, 5, 6, 3, '{"compensation": "Published pay: 10% per sale with a 30-day cookie, corroborated by two independent affiliate directories.", "contact_access": "No public partnerships email or brand-hosted application page was found; joining runs through ShareASale \u2014 lower band.", "credibility": "A smaller DTC coffee brand; credible sustainability partnerships (One Tree Planted) but limited public company footprint compared with national brands.", "niche_fit": "Cold brew coffee concentrate is a natural fit for food, coffee and morning-routine creators, with an easy at-home preparation story.", "opportunity_availability": "Creators apply through the ShareASale marketplace listing.", "ugc_evidence": "An established network affiliate program aimed at coffee bloggers and influencers, but no brand-run creator program or named creator partners were found."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Spotlight Oral Care', 'https://www.spotlightoralcare.com', 'Dentist-founded oral care brand from Galway, Ireland, founded in 2016 by dentists Dr Lisa Creaven, Dr Vanessa Creaven and Dr Barry Buckley. Spotlight sells clinically proven, vegan and cruelty-free toothpastes, teeth whitening products, sonic toothbrushes and water flossers online and through retailers including Boots, Tesco and Dunnes Stores.', 'Ireland', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'health'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', 'francesca@spotlightoralcare.com', 'https://uk.spotlightoralcare.com/pages/affiliates', 'https://uk.spotlightoralcare.com/pages/affiliates', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 6, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://uk.spotlightoralcare.com/pages/affiliates.', 'https://uk.spotlightoralcare.com/pages/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Spotlight Oral Care Affiliate Program (Awin)', 'https://uk.spotlightoralcare.com/pages/affiliates', 'https://uk.spotlightoralcare.com/pages/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uk.spotlightoralcare.com/pages/affiliates', 'official_site', 'affiliate', 'Spotlight Oral Care''s official affiliate page gives step-by-step joining instructions for its Awin programme (programme number 25720, with a brand-supplied Awin verification code), states that affiliates who sign up this month earn 6% per sale, paid monthly with no minimum threshold, and names francesca@spotlightoralcare.com as the support contact. The page also notes Awin lets affiliates sign up using their Instagram data. ''No minimum threshold'' is a payout-threshold term, not an earnings cap, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/24739?setLocale=de_DE', 'affiliate_network', 'affiliate', 'Spotlight Oral Care''s Awin merchant profile confirms the commission structure: 6% standard commission, 10% cashback, 2% on voucher codes, 0% for gift vouchers, with average order value over £45. (Lasso''s directory instead claims 10% via Refersion; the brand''s own current Awin terms govern this entry.)', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://beautymatter.com/articles/spotlight-oral-care-raises-15-million', 'listing', 'general', 'BeautyMatter profiles Spotlight Oral Care as based in Galway, Ireland, founded in 2016 by Dr Lisa Creaven, Dr Vanessa Creaven and Dr Barry Buckley to build a clean, high-performance oral care brand; the brand has raised growth capital from Development Capital and sells through blue-chip retailers in Ireland, the UK, Europe and the US.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 11, 13, 8, 5, '{"compensation": "Published pay on the brand''s own page and network profile: 6% standard commission per sale (10% cashback tier), paid monthly with no minimum payout threshold.", "contact_access": "A public affiliate page with full joining instructions plus a named affiliate support email (francesca@spotlightoralcare.com) \u2014 top band per the rubric.", "credibility": "Dentist-founded 2016 brand headquartered in Galway with national retail distribution (Boots, Tesco, Dunnes) and institutional growth investment.", "niche_fit": "Oral care and teeth whitening sit at the health/beauty crossover that performs strongly in creator content, though the niche is narrower than skincare or supplements.", "opportunity_availability": "Signup is publicly open via Awin with a brand-supplied verification code that skips the bank-details step.", "ugc_evidence": "A formal affiliate programme with an influencer-friendly signup path (Awin registration using Instagram data) documented on the brand''s own page, though no named creator partners are published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('IPVanish', 'https://www.ipvanish.com/', 'IPVanish is a long-running consumer VPN service (Ziff Davis) selling monthly, quarterly and annual plans with apps for all major platforms. Its CJ Affiliate program pays a flat 50% commission on every plan, a rate structure that suits VPN review and privacy content.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'technology'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'CJ Affiliate', 50, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://wecantrack.com/programs/ipvanish-affiliate-program/.', 'https://wecantrack.com/programs/ipvanish-affiliate-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'IPVanish Affiliate Program — flat 50% on all plans via CJ Affiliate', 'https://wecantrack.com/programs/ipvanish-affiliate-program/', 'https://wecantrack.com/programs/ipvanish-affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://wecantrack.com/programs/ipvanish-affiliate-program/', 'program_listing', 'affiliate_program', 'IPVanish runs a CJ Affiliate program paying a flat 50% commission on all plans (monthly, quarterly and annual), with a 45-day cookie and commissions approved on day 31. The listing mentions no cap on payouts, but that is a third-party listing claim only, so the cap is recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkwhisper.com/ipvanish-affiliate-program/', 'program_listing', 'affiliate_program', 'Corroborating listings (LinkWhisper, PropellerAds) report the same CJ program at 50%. A separate direct program run on TUNE is reported elsewhere at up to 100% on first sales plus 35% recurring; the CJ program is the one recorded here.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 18, 8, 7, 4, '{"niche_fit": "VPNs are a core creator niche across YouTube, TikTok and blogs; privacy and streaming content converts well.", "ugc_evidence": "VPN reviews, speed tests and setup tutorials are proven UGC formats for this category.", "compensation": "Flat 50% on every plan through CJ is a strong, simple rate; no earnings cap is stated on any fetched source, so the cap is honestly unknown.", "contact_access": "No direct affiliate email was verified on a fetched page; contact runs through CJ Affiliate.", "opportunity_availability": "The CJ program is open to apply; approval runs through the network.", "credibility": "Established VPN brand owned by Ziff Davis with consistent terms reported across multiple program listings."}'::jsonb);
